	private List<ExclusiveGroup> exclusiveGroups(TupleExpr expression) {
		List<ExclusiveGroup> groups = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meetOther(QueryModelNode node) {
				if (node instanceof ExclusiveGroup group) {
					groups.add(group);
				}
				super.meetOther(node);
			}
		});
		return groups;
	}

	private List<FilterTuple> filteredOperands(TupleExpr expression) {
		List<FilterTuple> filtered = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meetOther(QueryModelNode node) {
				if (node instanceof FilterTuple tuple && tuple.getFilterExpr() != null) {
					filtered.add(tuple);
				}
				super.meetOther(node);
			}
		});
		return filtered;
	}

	private ExclusiveGroup assertAtomicGraphGroup(TupleExpr expression, int statementCount, IRI innerGraph) {
		List<ExclusiveGroup> groups = exclusiveGroups(expression);
		List<ExclusiveGroup> outer = groups.stream().filter(group -> {
			for (QueryModelNode parent = group.getParentNode(); parent != null; parent = parent.getParentNode()) {
				if (parent instanceof ExclusiveGroup) {
					return false;
				}
			}
			return true;
		}).toList();
		assertThat(outer).as(expression.toString()).hasSize(1);
		ExclusiveGroup atomic = outer.getFirst();
		assertThat(countNodes(atomic, ExclusiveStatement.class)).isEqualTo(statementCount);
		assertThat(exclusiveGroups(atomic)).filteredOn(group -> group != atomic && group.isVariableScopeChange())
				.singleElement()
				.satisfies(boundary -> {
					List<StatementPattern> statements = new ArrayList<>();
					boundary.visit(new AbstractQueryModelVisitor<RuntimeException>() {
						@Override
						public void meetOther(QueryModelNode node) {
							if (node instanceof ExclusiveStatement statement) {
								statements.add(statement);
							}
							super.meetOther(node);
						}
					});
					assertThat(statements).isNotEmpty().allSatisfy(statement -> {
						assertThat(statement.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
						assertThat(statement.getContextVar().getValue()).isEqualTo(innerGraph);
					});
				});
		return atomic;
	}

	private List<BindingSet> evaluateSingleRemoteRequest(FederationEvaluationStrategy strategy, TupleExpr expression,
			BindingSet input) {
		AtomicInteger requests = new AtomicInteger();
		repoSettings(1).setLatencySimulator(requests::incrementAndGet);
		try {
			List<BindingSet> rows = Iterations.asList(strategy.evaluate(expression, input));
			assertThat(requests).hasValue(1);
			return rows;
		} finally {
			repoSettings(1).setLatencySimulator(null);
		}
	}

	private int countNodes(TupleExpr expression, Class<? extends TupleExpr> nodeType) {
		int[] count = { 0 };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ArbitraryLengthPath node) {
				if (nodeType.isInstance(node)) {
					count[0]++;
				}
				super.meet(node);
			}

			@Override
			public void meetOther(org.eclipse.rdf4j.query.algebra.QueryModelNode node) {
				if (nodeType.isInstance(node)) {
					count[0]++;
				}
				super.meetOther(node);
			}
		});
		return count[0];
	}

	@Test
	public void boundAliasSelectionPreservesPhysicalContextAndEndpointOnlyDatasetSemantics() {
		IRI rdf4jAlias = VF.createIRI("http://rdf4j.org/schema/rdf4j#nil");
		IRI sesameAlias = VF.createIRI("http://www.openrdf.org/schema/sesame#nil");
		IRI ordinaryGraph = VF.createIRI("urn:ordinaryGraph");
		SimpleDataset dataset = new SimpleDataset();
		dataset.addNamedGraph(rdf4jAlias);
		dataset.addNamedGraph(sesameAlias);
		dataset.addNamedGraph(ordinaryGraph);
		StatementPattern fixedAlias = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g", rdf4jAlias, true, true));
		assertThat(FedXUtil.toContexts(fixedAlias, dataset)).containsExactly(rdf4jAlias);

		StatementPattern enumeratedGraphs = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g"));
		assertThat(FedXUtil.toContexts(enumeratedGraphs, dataset))
				.containsExactlyInAnyOrder(null, null, ordinaryGraph);
		assertThat(FedXUtil.isContextAvailable(fixedAlias, new FedXDataset(null))).isTrue();
		assertThat(FedXUtil.isContextAvailable(fixedAlias, new FedXDataset(new SimpleDataset()))).isTrue();
		assertThat(FedXUtil.toRdfDataset(new FedXDataset(null))).isNull();

		SimpleDataset queryDataset = new SimpleDataset();
		queryDataset.addNamedGraph(ordinaryGraph);
		Dataset queryFallback = FallbackDataset.fallback(new FedXDataset(null), queryDataset);
		assertThat(FedXUtil.toRdfDataset(queryFallback).getNamedGraphs()).containsExactly(ordinaryGraph);

		SimpleDataset primaryDataset = new SimpleDataset();
		primaryDataset.addNamedGraph(rdf4jAlias);
		Dataset primaryWins = FallbackDataset.fallback(new FedXDataset(primaryDataset), queryDataset);
		assertThat(FedXUtil.toRdfDataset(primaryWins).getNamedGraphs()).containsExactly(rdf4jAlias);
	}

